table.rows:
{
	labels = {
		"SUBMITTED": #('Submitted'@en, 'Angenommen'@de),
		"WORKING": #('Working'@en, 'In Arbeit'@de),
		"INPUT_REQUIRED": #('Waiting for input'@en, 'Wartet auf Antwort'@de),
		"AUTH_REQUIRED": #('Waiting for authorization'@en, 'Wartet auf Anmeldung'@de),
		"COMPLETED": #('Completed'@en, 'Abgeschlossen'@de),
		"FAILED": #('Failed'@en, 'Fehlgeschlagen'@de),
		"CANCELED": #('Cancelled'@en, 'Abgebrochen'@de),
		"REJECTED": #('Rejected'@en, 'Abgelehnt'@de)
	};
	// A state as the wire writes it (TASK_STATE_COMPLETED) or as the client tools answer it (COMPLETED).
	state = s -> {
		key = isEmpty($s) ? "" : regex("^TASK_STATE_").regexReplace(toString($s), "");
		label = $labels[$key];
		isEmpty($label) ? $key : $label.localize();
	};
	// A served task whose run was not recorded has no start; it sorts first.
	byTime = (x -> isEmpty($x["started"]) ? 0 : toMillis($x["started"])).comparator();
	// A model's answer often starts with blank lines, and a cell shows its first line.
	text = parts -> $parts.map(p -> $p["text"]).filter(t -> !isEmpty($t)).join(separator: "\n").trim();

	incoming = all(`tl.ai.execution:AgentSession`)
		.filter(s -> $s.get(`tl.ai.execution:AgentSession#kind`) == `tl.ai.execution:SessionKind#BACKGROUND`
			&& !isEmpty($s.get(`tl.ai.execution:AgentSession#metadata`))
			&& $s.get(`tl.ai.execution:AgentSession#metadata`).stringContains('"a2a"'))
		.map(s -> {
			a2a = parseJson($s.get(`tl.ai.execution:AgentSession#metadata`))["a2a"];
			runs = $s.referers(`tl.ai.execution:AgentExecution#session`)
				.indexBy(e -> $e.get(`tl.ai.execution:AgentExecution#runId`));
			tasks = $a2a["tasks"].values().map(r -> {
				t = $r["task"];
				run = $runs[$t["metadata"]["runId"]];
				{
					"id": $t["id"],
					"state": $state($t["status"]["state"]),
					"started": isEmpty($run) ? null : $run.get(`tl.ai.execution:AgentExecution#startedAt`),
					"ended": isEmpty($run) ? null : $run.get(`tl.ai.execution:AgentExecution#endedAt`),
					"run": $run,
					"messages": $t["history"].map(m -> {
						"from": $m["role"] == "ROLE_USER" ? $a2a["peer"] : $a2a["agent"],
						"text": $text($m["parts"])
					})
				};
			}).sort($byTime);
			peer = $a2a["peer"];
			caller = $a2a["caller"];
			{
				"direction": #('Incoming'@en, 'Eingehend'@de).localize(),
				"agent": $a2a["agent"],
				"remote": $peer == $caller ? $peer : $peer + " (" + $caller + ")",
				"topic": $tasks.firstElement()["messages"].firstElement()["text"],
				"state": $tasks.lastElement()["state"],
				"started": $s.get(`tl.ai.execution:AgentSession#createdAt`),
				"lastActivity": isEmpty($s.get(`tl.ai.execution:AgentSession#lastUpdated`))
					? $s.get(`tl.ai.execution:AgentSession#createdAt`)
					: $s.get(`tl.ai.execution:AgentSession#lastUpdated`),
				"tasks": $tasks
			};
		});

	tools = regex("askAgent|replyAgent|getAgentTask");
	// The facts the client tools state in the clear at the top of their answer ("taskId: ...").
	line = name -> regex("(?m)^" + $name + ": (.+)$");
	remoteLine = $line("Remote agent");
	taskLine = $line("taskId");
	contextLine = $line("contextId");
	stateLine = $line("state");
	topicLine = regex('(?m)^conversation: "(.*)"$');
	field = re -> answer -> $re.regexSearch($answer).regexGroup(1).firstElement();
	// What the remote agent wrote: the "answer:", "question:" or "message:" block inside the envelope.
	saidBlock = regex("(?s)(?:answer|question|message):\n(.*?)(?:\n+artifacts:|\n*</untrusted)");
	said = answer -> {
		text = $saidBlock.regexSearch($answer).regexGroup(1).firstElement();
		(isEmpty($text) ? $answer : $text).trim();
	};
	calls = all(`tl.ai.execution:AgentExecution`)
		.filter(e -> {
			raw = $e.get(`tl.ai.execution:AgentExecution#transcript`);
			!isEmpty($raw) && $tools.regexSearch($raw).size() > 0;
		})
		.flatMap(e -> parseJson($e.get(`tl.ai.execution:AgentExecution#transcript`))["turns"]
			.flatMap(t -> $t["assistantParts"])
			.filter(p -> $p["type"] == "tool_call" && $tools.regexSearch(toString($p["toolCallData"]["toolName"])).size() > 0)
			.map(p -> {
				answer = toString($p["toolCallData"]["result"]);
				args = $p["toolCallData"]["argsJson"];
				millis = $p["timestamp"];
				{
					"run": $e,
					"time": toDate($millis),
					"end": toDate($millis + (isEmpty($p["toolCallData"]["durationMs"]) ? 0 : $p["toolCallData"]["durationMs"])),
					"message": isEmpty($args) ? null : parseJson($args)["message"],
					"answer": $answer,
					"remote": $field($remoteLine)($answer),
					"taskId": $field($taskLine)($answer),
					"contextId": $field($contextLine)($answer),
					"state": $field($stateLine)($answer),
					"topic": $field($topicLine)($answer)
				};
			}))
		.filter(c -> !isEmpty($c["contextId"]) && $c["contextId"] != "null");
	outgoing = $calls.groupBy(c -> $c["contextId"]).values().map(group -> {
		sorted = $group.sort((c -> $c["time"]).comparator());
		first = $sorted.firstElement();
		last = $sorted.lastElement();
		agent = $first["run"].get(`tl.ai.execution:AgentExecution#agentName`);
		{
			"direction": #('Outgoing'@en, 'Ausgehend'@de).localize(),
			"agent": $agent,
			"remote": $first["remote"],
			"topic": isEmpty($first["topic"]) ? $first["message"] : $first["topic"],
			"state": $state($last["state"]),
			"started": $first["time"],
			"lastActivity": $last["end"],
			"tasks": $sorted.filter(c -> !isEmpty($c["taskId"])).groupBy(c -> $c["taskId"]).values().map(steps -> {
				end = $steps.lastElement();
				{
					"id": $end["taskId"],
					"state": $state($end["state"]),
					"started": $steps.firstElement()["time"],
					"ended": $end["end"],
					"run": $end["run"],
					"messages": $steps.flatMap(c -> [
						{"from": $agent, "text": $c["message"]},
						{"from": $c["remote"], "text": $said($c["answer"])}
					]).filter(m -> !isEmpty($m["text"]))
				};
			}).sort($byTime)
		};
	});

	concat($incoming, $outgoing);
}

t -> {
	raw = isEmpty($t["run"]) ? null : $t["run"].get(`tl.ai.execution:AgentExecution#transcript`);
	cut = s -> isEmpty($s) ? $s : (length($s) > 1000 ? subString($s, 0, 1000) + "…" : $s);
	isEmpty($raw) ? list() : parseJson($raw)["turns"]
		.flatMap(turn -> $turn["assistantParts"])
		.filter(p -> $p["type"] == "tool_call")
		.map(p -> {
			call = $p["toolCallData"];
			{
				"time": $p["timestamp"].toDate(),
				"tool": $call["toolName"],
				"status": $call["status"],
				"duration": $call["durationMs"],
				"arguments": $cut($call["argsJson"]),
				"result": $cut(isEmpty($call["errorMessage"]) ? $call["result"] : $call["errorMessage"])
			};
		});
}
